/*
 * TB6600 Stepper Motor Driver Example
 *
 * Controls a NEMA 17 stepper motor using TB6600 driver.
 * Demonstrates pulse/direction control with variable speed.
 *
 * Wiring:
 *   Arduino D2  -> TB6600 PUL (Pulse)
 *   Arduino D3  -> TB6600 DIR (Direction)
 *   Arduino D4  -> TB6600 ENA (Enable)
 *   Arduino GND -> TB6600 GND
 *
 * TB6600 Settings:
 *   - Microstep: 1/16 (DIP switches SW1-SW4)
 *   - Current: 1.5A (potentiometer adjustment)
 *   - Motor: NEMA 17 (1.8° step angle)
 *
 * Step Angle Calculation:
 *   Full step = 1.8°
 *   1/16 microstep = 1.8° / 16 = 0.1125° per microstep
 *   Steps per revolution = 360° / 0.1125° = 3200 microsteps
 */

#include <TB6600.h>

// Pin definitions
const int PUL_PIN = 2;   // Pulse pin
const int DIR_PIN = 3;   // Direction pin
const int ENA_PIN = 4;   // Enable pin

// Create TB6600 driver instance
TB6600 stepper(PUL_PIN, DIR_PIN, ENA_PIN);

// Microstep setting (must match DIP switch configuration)
const int MICROSTEP = 16;

// Steps per revolution for 1.8° stepper with 1/16 microstep
// 360° / (1.8° / 16) = 3200 steps per revolution
const int STEPS_PER_REV = 3200;

void setup() {
  Serial.begin(115200);
  Serial.println("TB6600 Stepper Motor Control");
  Serial.println("==========================");

  // Initialize the driver
  stepper.begin();
  stepper.setMicrostep(MICROSTEP);
  stepper.setSpeed(800);  // 800 pulses per second

  Serial.print("Microstep: 1/");
  Serial.println(MICROSTEP);
  Serial.print("Steps per revolution: ");
  Serial.println(STEPS_PER_REV);
  Serial.println();
}

void loop() {
  // Example 1: Rotate clockwise at slow speed
  Serial.println("[1] Rotating CW at 200 RPM...");
  stepper.setSpeed(200);
  stepper.enable();
  stepper.step(STEPS_PER_REV);  // One full revolution CW
  delay(1000);

  // Example 2: Rotate counter-clockwise at medium speed
  Serial.println("[2] Rotating CCW at 400 RPM...");
  stepper.setSpeed(400);
  stepper.step(-STEPS_PER_REV);  // One full revolution CCW
  delay(1000);

  // Example 3: Rotate clockwise at high speed
  Serial.println("[3] Rotating CW at 600 RPM...");
  stepper.setSpeed(600);
  stepper.step(STEPS_PER_REV);
  delay(1000);

  // Example 4: Partial rotation (90 degrees)
  Serial.println("[4] Rotating 90° CW...");
  stepper.setSpeed(400);
  stepper.step(STEPS_PER_REV / 4);  // 90 degrees
  delay(500);

  // Example 5: Return to starting position
  Serial.println("[5] Returning to start...");
  stepper.step(-STEPS_PER_REV / 4);  // -90 degrees
  delay(1000);

  // Example 6: Disable motor (torque off)
  Serial.println("[6] Motor disabled (torque off)");
  stepper.disable();
  delay(2000);

  // Re-enable for next cycle
  Serial.println("[7] Motor re-enabled");
  stepper.enable();
  delay(500);

  Serial.println("--- Cycle complete ---");
  Serial.println();
  delay(1000);
}
